          totalMs == other.totalMs;
}

/// Where a spend is proved.
enum Proving {
  /// On the device, with the pinned proving key for its shape. The witness
  /// stays in this process.
  local,

  /// By the prover at [`WalletConfig::prover_url`](crate::WalletConfig::prover_url),
  /// through the application's transport. The prover receives the witness,
  /// the wallet's nullifier secret included.
  remote,
}

/// Where a [`ProvingKeys::prefetch`] is.
class ProvingKeyProgress {
  /// The key downloading now.
  final String name;
  final BigInt keyDownloaded;
  final BigInt keySize;

  /// Keys complete so far, of `keys_total` that were not on the device
  /// when the prefetch started.
  final int keysDone;
  final int keysTotal;

  /// Bytes on the device of those keys, of `total`.
  final BigInt downloaded;
  final BigInt total;

  const ProvingKeyProgress({
    required this.name,
    required this.keyDownloaded,
    required this.keySize,
    required this.keysDone,
    required this.keysTotal,
    required this.downloaded,
    required this.total,
  });

  @override
  int get hashCode =>
      name.hashCode ^
      keyDownloaded.hashCode ^
      keySize.hashCode ^
      keysDone.hashCode ^
      keysTotal.hashCode ^
      downloaded.hashCode ^
      total.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is ProvingKeyProgress &&
          runtimeType == other.runtimeType &&
          name == other.name &&
          keyDownloaded == other.keyDownloaded &&
          keySize == other.keySize &&
          keysDone == other.keysDone &&
          keysTotal == other.keysTotal &&
          downloaded == other.downloaded &&
          total == other.total;
}

/// A proving key of the wallet and how much of it is on the device.
class ProvingKeyStatus {
  final String name;

  /// The key's size in the lockfile.
  final BigInt size;

  /// Bytes on the device: `size` once it downloaded, what an interrupted
  /// download left otherwise.
  final BigInt downloaded;

  const ProvingKeyStatus({
    required this.name,
    required this.size,
    required this.downloaded,
  });

  @override
  int get hashCode => name.hashCode ^ size.hashCode ^ downloaded.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is ProvingKeyStatus &&
          runtimeType == other.runtimeType &&
          name == other.name &&
          size == other.size &&
          downloaded == other.downloaded;
}

/// Whether the user registry publishes this wallet's shielded address.
enum RegistrationStatus {
  /// No record: others cannot pay this account privately yet.
  notRegistered,

  /// The record holds this wallet's keys.
  registered,

  /// The record holds other keys: registered by another client, rotated, or
  /// derived by a signer whose signatures differ between calls. Payments to
  /// this account go to those keys, not to this wallet.
  conflict,
}

/// The most one spend of up to `outputs` outputs, change included, can take
/// now without a merge: from the unreserved notes, largest first, within the
/// note cap of that width and two trees.
class SpendLimit {
  final BigInt outputs;
  final BigInt amount;

  const SpendLimit({required this.outputs, required this.amount});

  @override
  int get hashCode => outputs.hashCode ^ amount.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is SpendLimit &&
          runtimeType == other.runtimeType &&
          outputs == other.outputs &&
          amount == other.amount;
}

/// A spendable private balance. `mint` is `None` for SOL.
///
/// `amount` is what the indexer has confirmed for this wallet, `reserved`
/// included: a payment or change on its way appears once its transaction is
/// confirmed and indexed. Reservations live in this open wallet's memory
/// only.
class TokenBalance {
  final String? mint;
  final BigInt amount;

  /// How many spendable notes the amount is in: what a spend of all of it
  /// takes, and what a merge reduces.
  final BigInt notes;

  /// The part of `amount` in notes this wallet's prepared spends hold.
  final BigInt reserved;

  /// One entry per proof width the pinned shapes offer (2, 4, 8 and 16
  /// outputs), ascending. A spend with `k` private outputs proves with
  /// `k + 1` outputs, its change included, and public outputs take no
  /// slot: a withdrawal, a withdrawal with one private fee, or a send to
  /// one wallet reads the entry with `outputs: 2`, a send to one wallet
  /// with a fee the entry with `outputs: 4`. The limits include any
  /// application fee the spend pays.
  final List<SpendLimit> limits;

  const TokenBalance({
    this.mint,
    required this.amount,
    required this.notes,
    required this.reserved,
    required this.limits,
  });

  @override
  int get hashCode =>
      mint.hashCode ^
      amount.hashCode ^
      notes.hashCode ^
      reserved.hashCode ^
      limits.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is TokenBalance &&
          runtimeType == other.runtimeType &&
          mint == other.mint &&
          amount == other.amount &&
          notes == other.notes &&
          reserved == other.reserved &&
          limits == other.limits;
}

/// A signature-scoped read. Network failures throw; they are never empty
/// wallet results. Only `ready` may carry entries.
class TransactionLookup {
  final TransactionLookupStatus status;
  final List<ActivityEntry> entries;
  final BigInt? slot;

  /// Highest slot the indexer had persisted for this lookup.
  final BigInt indexedSlot;

  const TransactionLookup({
    required this.status,
    required this.entries,
    this.slot,
    required this.indexedSlot,
  });

  @override
  int get hashCode =>
      status.hashCode ^ entries.hashCode ^ slot.hashCode ^ indexedSlot.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is TransactionLookup &&
          runtimeType == other.runtimeType &&
          status == other.status &&
          entries == other.entries &&
          slot == other.slot &&
          indexedSlot == other.indexedSlot;
}

/// Whether a signature has a complete wallet result at the indexed slot.
enum TransactionLookupStatus {
  /// The complete result for configured assets. `entries` may be empty.
  ready,

  /// The confirmed transaction's slot is ahead of the indexer. Retry later.
  pendingIndexing,

  /// Neither the indexer nor the confirmed RPC returned the transaction.
  /// This does not prove it never existed: the RPC may prune old history.
  notFound,

  /// The transaction was found, but this SDK cannot reconstruct every
  /// wallet row from its format, ciphertexts or available RPC metadata.
  /// No partial entries are returned and no history scan is attempted.
  incomplete,
}

/// Why the application's transport has no response.
class TransportFailure {
  final String message;

  /// The response's status, when it arrived and its body could not be read.
  /// The server got the request and may have acted on it, so the wallet does
  /// not send it again: a prover would prove the spend twice.
  final int? status;

  const TransportFailure({required this.message, this.status});

  @override
  int get hashCode => message.hashCode ^ status.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is TransportFailure &&
          runtimeType == other.runtimeType &&
          message == other.message &&
          status == other.status;
}

/// What the application's transport answered: the server's response, or the
/// failure that left none. The package's Dart side builds it and never
/// throws, so no Dart stack trace reaches the wallet.
class TransportOutcome {
  final TransportResponse? response;
  final TransportFailure? failure;

  const TransportOutcome({this.response, this.failure});

  @override
  int get hashCode => response.hashCode ^ failure.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is TransportOutcome &&
          runtimeType == other.runtimeType &&
          response == other.response &&
          failure == other.failure;
}

/// One HTTP request of the wallet.
class TransportRequest {
  /// `POST` for Solana RPC and indexer calls and proof requests, `GET` for
  /// proving keys and the status of a queued proof.
  final String method;
  final String url;

  /// The content type of a `POST`, `x-sync` or `x-async` on a proof
  /// request, and `range` on a proving-key download; nothing else.
  final Map<String, String> headers;

  /// Empty for a `GET`. A proof request's body is the transaction's
  /// witness, the wallet's nullifier secret included.
  final Uint8List body;

  /// The most bytes the response body may hold, for a proving-key download
  /// (the size of the part it asks for). A transport stops reading and
  /// fails past it; the wallet refuses a longer body either way.
  final int? maxResponseBytes;

  /// The caller's bound on the request, in milliseconds, when it has one
  /// (600 s for a proof request, 30 s for a status poll); otherwise the
  /// transport's own applies.
  final int? timeoutMs;

  /// For a proving-key download: the file to write the body, a part of the
  /// key, to as it arrives. The response then carries no body. The wallet
  /// appends the part to the key and checks the key once it is complete. A
  /// transport that returns the body instead still works, holding the part
  /// in memory.
  final String? downloadPath;

  const TransportRequest({
    required this.method,
    required this.url,
    required this.headers,
    required this.body,
    this.maxResponseBytes,
    this.timeoutMs,
    this.downloadPath,
  });

  @override
  int get hashCode =>
      method.hashCode ^
      url.hashCode ^
      headers.hashCode ^
      body.hashCode ^
      maxResponseBytes.hashCode ^
      timeoutMs.hashCode ^
      downloadPath.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is TransportRequest &&
          runtimeType == other.runtimeType &&
          method == other.method &&
          url == other.url &&
          headers == other.headers &&
          body == other.body &&
          maxResponseBytes == other.maxResponseBytes &&
          timeoutMs == other.timeoutMs &&
          downloadPath == other.downloadPath;
}

/// The server's response, whatever its status.
class TransportResponse {
  final int status;

  /// The response's headers as they arrived. A prover inside a TEE says in
  /// them that its body is encrypted; a TEE call fails without them.
  final Map<String, String> headers;
  final Uint8List body;

  const TransportResponse({
    required this.status,
    required this.headers,
    required this.body,
  });

  @override
  int get hashCode => status.hashCode ^ headers.hashCode ^ body.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is TransportResponse &&
          runtimeType == other.runtimeType &&
          status == other.status &&
          headers == other.headers &&
          body == other.body;
}

/// Assets of wallet notes that could not be resolved after refreshing the
/// pool's registrations. Their notes are excluded from balances and activity.
/// This also includes mints excluded by [`WalletConfig::mints`].
class UnresolvedAssets {
  /// Unresolved asset ids, sorted and deduplicated. These are supplied by
  /// senders and may not correspond to a registered asset.
  final Uint64List assetIds;

  /// Base58 mints from deposits or merge outputs with no known asset id.
  final List<String> mints;

  const UnresolvedAssets({required this.assetIds, required this.mints});

  @override
  int get hashCode => assetIds.hashCode ^ mints.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is UnresolvedAssets &&
          runtimeType == other.runtimeType &&
          assetIds == other.assetIds &&
          mints == other.mints;
}

/// Where the wallet reads chain state and stores proving keys.
class WalletConfig {
  final String rpcUrl;
  final String indexerUrl;

  /// Directory for downloaded proving keys; keep it across launches.
  final String provingKeyDir;

  /// Overrides [`crate::DEFAULT_PROVING_KEYS_URL`].
  final String? provingKeyUrl;

  /// Where spends are proved unless a call says otherwise: on the device
  /// when `None`. [`Proving::Remote`] needs [`Self::prover_url`].
  final Proving? proving;

  /// The prover [`Proving::Remote`] asks, through the transport: the
  /// application's backend as a proxy of the prover's routes, or a Zolana
  /// prover. It receives each spend's witness, the wallet's nullifier
  /// secret included, encrypted to the enclave the Zolana SDK pins once the
  /// prover attests to it; only a loopback prover gets it in plaintext.
  final String? proverUrl;

  /// The most notes a spend takes on the device, 1 to 40; 40 when `None`.
  /// A spend that needs more fails with [`WalletError::MergeRequired`]
  /// naming this cap, before proving. Proof time and memory grow with the
  /// notes a spend takes: a low cap, with merges that keep the notes few,
  /// keeps spends fast.
  final int? maxSpendInputs;

  /// For how many milliseconds a spend may take its notes from the last
  /// read ([`MobileWallet::balances`], [`MobileWallet::overview`],
  /// [`MobileWallet::private_balance`] or [`MobileWallet::activity`])
  /// instead of reading the indexer again; `None` reads before every
  /// spend. A send or a confirmation ends the reuse. A note spent
  /// elsewhere since the read fails the spend when it is sent, with
  /// [`WalletError::NotesAlreadySpent`], as a note spent right after a
  /// read would.
  final BigInt? reuseNotesMs;

  /// The SPL mints the wallet holds, each with its token program. A call
  /// that names another mint fails with [`WalletError::MintNotConfigured`],
  /// and [`MobileWallet::balances`] reports SOL and these only; notes in
  /// other mints are left out. `None` holds every mint the shielded pool
  /// registered: the wallet looks up a mint a call names, and the mints of
  /// notes a read meets.
  final List<MintConfig>? mints;

  /// Default total priority fee per transaction, in lamports. Each prepare
  /// call can override it, including with zero. `None` adds no priority fee.
  final BigInt? priorityFeeLamports;

  const WalletConfig({
    required this.rpcUrl,
    required this.indexerUrl,
    required this.provingKeyDir,
    this.provingKeyUrl,
    this.proving,
    this.proverUrl,
    this.maxSpendInputs,
    this.reuseNotesMs,
    this.mints,
    this.priorityFeeLamports,
  });

  @override
  int get hashCode =>
      rpcUrl.hashCode ^
      indexerUrl.hashCode ^
      provingKeyDir.hashCode ^
      provingKeyUrl.hashCode ^
      proving.hashCode ^
      proverUrl.hashCode ^
      maxSpendInputs.hashCode ^
      reuseNotesMs.hashCode ^
      mints.hashCode ^
      priorityFeeLamports.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is WalletConfig &&
          runtimeType == other.runtimeType &&
          rpcUrl == other.rpcUrl &&
          indexerUrl == other.indexerUrl &&
          provingKeyDir == other.provingKeyDir &&
          provingKeyUrl == other.provingKeyUrl &&
          proving == other.proving &&
          proverUrl == other.proverUrl &&
          maxSpendInputs == other.maxSpendInputs &&
          reuseNotesMs == other.reuseNotesMs &&
          mints == other.mints &&
          priorityFeeLamports == other.priorityFeeLamports;
}

@freezed
