    required this.viewingPrivateKey,
    required this.viewingPublicKey,
    required this.nullifierPrivateKey,
    required this.nullifierPublicKey,
  });

  @override
  int get hashCode =>
      viewingPrivateKey.hashCode ^
      viewingPublicKey.hashCode ^
      nullifierPrivateKey.hashCode ^
      nullifierPublicKey.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is WalletKeys &&
          runtimeType == other.runtimeType &&
          viewingPrivateKey == other.viewingPrivateKey &&
          viewingPublicKey == other.viewingPublicKey &&
          nullifierPrivateKey == other.nullifierPrivateKey &&
          nullifierPublicKey == other.nullifierPublicKey;
}

/// The private balances, one per asset held, and the history, newest first.
/// Notes in [`Self::unresolved_assets`] are excluded from both.
class WalletOverview {
  final List<TokenBalance> balances;
  final List<ActivityEntry> activity;
  final UnresolvedAssets unresolvedAssets;

  const WalletOverview({
    required this.balances,
    required this.activity,
    required this.unresolvedAssets,
  });

  @override
  int get hashCode =>
      balances.hashCode ^ activity.hashCode ^ unresolvedAssets.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is WalletOverview &&
          runtimeType == other.runtimeType &&
          balances == other.balances &&
          activity == other.activity &&
          unresolvedAssets == other.unresolvedAssets;
}
